mapper.select:
SELECT FP.FINPROD_ID finprodId, /**产品代码*/ FP.FINPROD_ABBR finprodName, /**产品名称*/ TBBS.HAPPEN_DATE happenDate, /**发生日期*/ TBBS.TAX_P_TYPE taxPType, /**业务类型*/ TBBS.VAT_TYPE vatType, /**收入类型*/ (case when TBBS.TAX_P_TYPE='01' then SUM(TAX_AMT) else null end) AS taxAmt, /**预估税费余额*/ (case when TBBS.TAX_P_TYPE='02' then SUM(TAX_AMT) else null end) AS taxAmt2 /**发生税费余额*/ FROM TAX_BOK_BALANCE_SUM TBBS LEFT JOIN FIN_PRODUCT FP ON TBBS.BOOKSET_ID=FP.FINPROD_ID WHERE 1=1
AND TBBS.VAT_TYPE in
#{type}
AND TBBS.BOOKSET_ID in
#{finprodId}
AND TBBS.TAX_P_TYPE in
#{pType}
AND TBBS.VAT_TYPE in
#{vatType}
AND TBBS.HAPPEN_DATE <= STR_TO_DATE(#{endDate },'%Y-%m-%d') AND TBBS.HAPPEN_DATE >= STR_TO_DATE(#{startDate },'%Y-%m-%d')
GROUP BY FP.FINPROD_ID, FP.FINPROD_ABBR, TBBS.HAPPEN_DATE, TBBS.TAX_P_TYPE, TBBS.VAT_TYPE
HAVING SUM(TAX_AMT) != 0

SELECT FP.FINPROD_ID finprodId, /**产品代码*/ FP.FINPROD_ABBR finprodName, /**产品名称*/ BDI.BUSI_ID assetId, /**资产代码*/ FP2.FINPROD_ABBR assetIdName, /**资产名称*/ TBBS.HAPPEN_DATE happenDate, /**发生日期*/ TBBS.TAX_P_TYPE taxPType, /**业务类型*/ TBBS.VAT_TYPE vatType, /**收入类型*/ (case when TBBS.TAX_P_TYPE='01' then SUM(TAX_AMT) else null end) AS taxAmt, /**预估税费余额*/ (case when TBBS.TAX_P_TYPE='02' then SUM(TAX_AMT) else null end) AS taxAmt2 /**发生税费余额*/ FROM TAX_BOK_BALANCE TBBS LEFT JOIN FIN_PRODUCT FP ON TBBS.BOOKSET_ID=FP.FINPROD_ID LEFT JOIN BOK_DETAIL_ID BDI ON TBBS.BOK_DETAIL_ID = BDI.BOK_DETAIL_ID and FP.FINPROD_ID=BDI.BOOKSET_ID LEFT JOIN FIN_PRODUCT FP2 ON BDI.BUSI_ID = FP2.FINPROD_ID WHERE 1=1 AND TBBS.VAT_TYPE in
#{type}
AND TBBS.BOOKSET_ID in
#{finprodId}
AND TBBS.TAX_P_TYPE in
#{pType}
AND TBBS.VAT_TYPE in
#{vatType}
AND TBBS.HAPPEN_DATE <= STR_TO_DATE(#{endDate },'%Y-%m-%d') AND TBBS.HAPPEN_DATE >= STR_TO_DATE(#{startDate },'%Y-%m-%d')
AND BDI.BUSI_ID in
#{assetId}
GROUP BY FP.FINPROD_ID, FP.FINPROD_ABBR, TBBS.HAPPEN_DATE, TBBS.TAX_P_TYPE, TBBS.VAT_TYPE, BDI.BUSI_ID, FP2.FINPROD_ABBR
HAVING SUM(TAX_AMT) != 0
